import { z } from 'zod';
import { planCodeSchema } from '@/schema/api/payments/toss';

// 통화별 가격 정보
const currencyPriceSchema = z.object({
  totalAmount: z.number().int().nonnegative(),
  monthlyEquivalentAmount: z.number().int().nonnegative()
});

// 플랜 가격 정보 스키마 (백엔드 원본)
const rawPlanSchema = z.object({
  planCode: planCodeSchema,
  displayName: z.string(),
  durationMonths: z.number().int().positive(),
  prices: z.object({
    KRW: currencyPriceSchema,
    USD: currencyPriceSchema
  })
});

// 프론트에서 사용하기 편한 형태로 변환
export const planSchema = rawPlanSchema.transform((raw) => ({
  planCode: raw.planCode,
  displayName: raw.displayName,
  durationMonths: raw.durationMonths,
  prices: raw.prices,
  // 편의 필드: KRW 기준 (useProductPrices 훅에서 언어별 분기)
  totalAmount: raw.prices.KRW.totalAmount,
  monthlyEquivalentAmount: raw.prices.KRW.monthlyEquivalentAmount
}));

export type Plan = z.infer<typeof planSchema>;

// 플랜 가격 목록 데이터 스키마
export const planPricesDataSchema = z.object({
  plans: z.array(planSchema)
});

// 플랜 가격 목록 응답 스키마 (백엔드 래핑)
export const getProductPricesResponseSchema = z.object({
  data: planPricesDataSchema
});

export type GetProductPricesResponse = z.infer<
  typeof getProductPricesResponseSchema
>;

// planCode 타입
export type PlanCode = z.infer<typeof planCodeSchema>;
