import { Check } from 'lucide-react';
import {
  StyledStepperBar,
  StyledStepperRow,
  StyledStep,
  StyledStepCircle,
  StyledStepName,
  StyledStepLine,
} from './InstantStepper.style';

const STEPS = [
  { label: '양식 선택' },
  { label: '프롬프트' },
  { label: '자료 업로드' },
  { label: '이미지 선택' },
  { label: '문서 세부 설정' },
  { label: '생성' },
] as const;

interface InstantStepperProps {
  currentStep: number;
  hideFirstStep?: boolean;
  // #23: onStepClick 제거 → 스텝퍼 클릭으로 단계 이동 전면 불가
}

export function InstantStepper({ currentStep, hideFirstStep }: InstantStepperProps) {
  const steps = hideFirstStep ? STEPS.slice(1) : STEPS;
  const offset = hideFirstStep ? 1 : 0;

  return (
    <StyledStepperBar>
      <StyledStepperRow>
        {steps.map((step, i) => {
          const num = i + 1 + offset;
          const displayNum = i + 1;
          const state: 'done' | 'active' | 'pending' =
            num < currentStep ? 'done' : num === currentStep ? 'active' : 'pending';

          return (
            <div key={num} style={{ display: 'flex', alignItems: 'flex-start' }}>
              {/* #23: clickable 제거, cursor default */}
              <StyledStep $clickable={false}>
                <StyledStepCircle $state={state}>
                  {state === 'done' ? <Check size={18} strokeWidth={3} /> : displayNum}
                </StyledStepCircle>
                <StyledStepName $state={state}>{step.label}</StyledStepName>
              </StyledStep>
              {i < steps.length - 1 && <StyledStepLine $done={num < currentStep} />}
            </div>
          );
        })}
      </StyledStepperRow>
    </StyledStepperBar>
  );
}
