import type { Theme } from '@docshunt/docs-editor-wasm';
import { z } from 'zod';

const publicIdSchema = z.union([z.string(), z.number()]).transform(String);
const themeSchema = z.custom<Theme>(() => true);

const promptFormDataSchema = z.object({
  prompt: z.string().optional(),
  draft: z.string().optional(),
  referenceFileIds: z.array(z.string()).optional(),
  selectedProductId: publicIdSchema.optional(),
  resolvedPrompt: z.string().optional(),
  productContents: z.string().optional(),
  exportProductFileId: publicIdSchema.optional()
}).passthrough();

const uploadDataSchema = z.object({
  referenceFileIds: z.array(z.string()).optional(),
  selectedProductId: publicIdSchema.optional(),
  exportProductFileId: publicIdSchema.optional(),
  productContents: z.string().optional()
}).passthrough();

const visualSuggestionSchema = z.object({
  id: z.string(),
  title: z.string(),
  prompt: z.string(),
  position: z.string(),
  genBy: z.enum(['ai', 'human']),
  selected: z.boolean()
});

const baseFunnelContextSchema = z.object({
  productFileId: publicIdSchema,
  fileName: z.string().optional(),
  templateFileId: publicIdSchema.optional(),
  formData: promptFormDataSchema.optional(),
  uploadData: uploadDataSchema.optional(),
  visualSuggestions: z.array(visualSuggestionSchema).optional(),
  theme: themeSchema.optional()
}).passthrough();

const funnelSessionSchema = z.discriminatedUnion('step', [
  z.object({
    step: z.literal('template')
  }),
  z.object({
    step: z.literal('prompt'),
    context: baseFunnelContextSchema
  }),
  z.object({
    step: z.literal('upload'),
    context: baseFunnelContextSchema
  }),
  z.object({
    step: z.literal('visual-suggestions'),
    context: baseFunnelContextSchema
  }),
  z.object({
    step: z.literal('settings'),
    context: baseFunnelContextSchema
  }),
  z.object({
    step: z.literal('output'),
    context: z.object({
      productFileId: publicIdSchema,
      templateFileId: publicIdSchema.optional(),
      fileName: z.string().optional()
    }).passthrough()
  })
]);

export type FunnelSession = z.output<typeof funnelSessionSchema>;
export type FillVisualSuggestion = z.output<typeof visualSuggestionSchema>;
export type FillFunnelContext = z.output<typeof baseFunnelContextSchema>;
export type FillFunnelStep = 'prompt' | 'upload' | 'visual-suggestions' | 'settings';
export type PromptFunnelContext = Extract<
  FunnelSession,
  { step: 'prompt' }
>['context'];
export type VisualSuggestionsFunnelContext = Extract<
  FunnelSession,
  { step: 'visual-suggestions' }
>['context'];
export type OutputFunnelContext = Extract<
  FunnelSession,
  { step: 'output' }
>['context'];

const FUNNEL_STORAGE_KEY = 'f-funnel-data';

const parseFunnelSession = (saved: string): FunnelSession | null => {
  try {
    const parsed = JSON.parse(saved);
    const result = funnelSessionSchema.safeParse(parsed);

    if (!result.success) {
      return null;
    }

    return result.data;
  } catch {
    return null;
  }
};

const serializeFunnelSession = (session: FunnelSession) =>
  JSON.stringify(session);

const getSessionStorage = () => {
  if (typeof window === 'undefined') {
    return null;
  }

  return window.sessionStorage;
};

const isFillFunnelSession = (
  session: FunnelSession | null
): session is Extract<FunnelSession, { step: FillFunnelStep }> =>
  session !== null &&
  session.step !== 'template' &&
  session.step !== 'output';

export const readFunnelSession = (): FunnelSession | null => {
  const storage = getSessionStorage();
  if (!storage) return null;

  const saved = storage.getItem(FUNNEL_STORAGE_KEY);
  if (!saved) return null;

  return parseFunnelSession(saved);
};

export const writeFunnelSession = (session: FunnelSession) => {
  const storage = getSessionStorage();
  if (!storage) return;

  const serialized = serializeFunnelSession(session);
  if (storage.getItem(FUNNEL_STORAGE_KEY) === serialized) {
    return;
  }

  storage.setItem(FUNNEL_STORAGE_KEY, serialized);
};

export const clearFunnelSession = () => {
  const storage = getSessionStorage();
  if (!storage) return;

  storage.removeItem(FUNNEL_STORAGE_KEY);
};

export const writeTemplateFunnelSession = () => {
  writeFunnelSession({ step: 'template' });
};

export const normalizeFunnelSessionStorage = (): FunnelSession | null => {
  const storage = getSessionStorage();
  if (!storage) return null;

  const saved = storage.getItem(FUNNEL_STORAGE_KEY);
  if (!saved) return null;

  const session = parseFunnelSession(saved);
  if (!session) {
    storage.removeItem(FUNNEL_STORAGE_KEY);
    return null;
  }

  const normalized = serializeFunnelSession(session);
  if (saved !== normalized) {
    storage.setItem(FUNNEL_STORAGE_KEY, normalized);
  }

  return session;
};

export const readFillFunnelContext = ({
  productFileId,
  steps
}: {
  productFileId?: string;
  steps?: FillFunnelStep[];
} = {}): FillFunnelContext | null => {
  const session = readFunnelSession();

  if (!isFillFunnelSession(session)) {
    return null;
  }

  if (steps && !steps.includes(session.step)) {
    return null;
  }

  if (
    typeof productFileId === 'string' &&
    session.context.productFileId !== productFileId
  ) {
    return null;
  }

  return session.context;
};

export const upsertFillFunnelContext = ({
  step,
  productFileId,
  patch
}: {
  step: FillFunnelStep;
  productFileId: string;
  patch?: Partial<FillFunnelContext>;
}): FillFunnelContext | null => {
  const previousContext = readFillFunnelContext({ productFileId });
  const sanitizedPatch = Object.fromEntries(
    Object.entries(patch ?? {}).filter(([, value]) => value !== undefined)
  ) as Partial<FillFunnelContext>;
  const nextSession = funnelSessionSchema.safeParse({
    step,
    context: {
      ...(previousContext ?? {}),
      ...sanitizedPatch,
      productFileId
    }
  });

  if (!nextSession.success) {
    return null;
  }

  writeFunnelSession(nextSession.data);

  return (
    nextSession.data as Extract<FunnelSession, { step: FillFunnelStep }>
  ).context;
};

export const readFillVisualSuggestions = ({
  productFileId,
  steps
}: {
  productFileId?: string;
  steps?: FillFunnelStep[];
} = {}): FillVisualSuggestion[] =>
  readFillFunnelContext({
    productFileId,
    steps
  })?.visualSuggestions ?? [];

export const writeFillVisualSuggestions = ({
  step,
  productFileId,
  fileName,
  suggestions
}: {
  step: FillFunnelStep;
  productFileId: string;
  fileName?: string;
  suggestions: FillVisualSuggestion[];
}) =>
  upsertFillFunnelContext({
    step,
    productFileId,
    patch: {
      ...(typeof fileName === 'string' ? { fileName } : {}),
      visualSuggestions: suggestions
    }
  });

export const writeOutputFunnelContext = (
  context: OutputFunnelContext
): OutputFunnelContext | null => {
  const nextSession = funnelSessionSchema.safeParse({
    step: 'output',
    context
  });

  if (!nextSession.success) {
    return null;
  }

  writeFunnelSession(nextSession.data);

  return (nextSession.data as Extract<FunnelSession, { step: 'output' }>).context;
};

export const readPromptFunnelContext = (
  productFileId: string
): PromptFunnelContext | null => {
  return (
    readFillFunnelContext({
      productFileId,
      steps: ['prompt']
    }) ?? null
  );
};

export const readOutputFunnelContext = (): OutputFunnelContext | null => {
  const session = readFunnelSession();

  return session?.step === 'output' ? session.context : null;
};

export const readVisualSuggestionsFunnelContext =
  (): VisualSuggestionsFunnelContext | null => {
    return (
      readFillFunnelContext({
        steps: ['visual-suggestions']
      }) ?? null
    );
  };
