import type { ProductFilePathMapContents } from '@/schema/api/products/products';

export type DraftPromptProfile =
  | 'business_plan'
  | 'rnd_plan'
  | 'everyone_startup';

export interface DraftTemplateOption {
  id: string;
  name: string;
  promptProfile: DraftPromptProfile;
  displayOrder?: number;
  isFreeDraftTemplate?: boolean;
}

type DraftTemplateOptionLike =
  | Pick<DraftTemplateOption, 'promptProfile' | 'isFreeDraftTemplate'>
  | null
  | undefined;

export const isEveryoneStartupDraftTemplate = (
  template: DraftTemplateOptionLike
) => template?.promptProfile === 'everyone_startup';

export const isFreeDraftTemplate = (template: DraftTemplateOptionLike) =>
  template?.isFreeDraftTemplate ?? isEveryoneStartupDraftTemplate(template);

const FILE_EXTENSION_PATTERN = /\.(hwp|hwpx|docx|pdf)$/i;
const normalizeTemplateName = (value: string) => value.normalize('NFC');

export const getDraftTemplateName = (filePath: string | null): string => {
  const fileName = filePath?.split('/').pop();

  if (!fileName) {
    return '초안 템플릿';
  }

  const normalizedFileName = normalizeTemplateName(fileName);

  return (
    normalizedFileName.replace(FILE_EXTENSION_PATTERN, '') || normalizedFileName
  );
};

export const resolveDraftPromptProfile = (
  templateName: string
): DraftPromptProfile => {
  const normalizedTemplateName = normalizeTemplateName(templateName);
  const normalizedName = normalizedTemplateName
    .replace(/\s+/g, '')
    .toLowerCase();
  const compactName = normalizedTemplateName
    .replace(/[^0-9a-zA-Z가-힣]/g, '')
    .toLowerCase();

  if (
    compactName.includes('모두의창업') ||
    (normalizedTemplateName.includes('모두의') &&
      normalizedTemplateName.includes('창업'))
  ) {
    return 'everyone_startup';
  }

  if (
    /r\s*&?\s*d/i.test(normalizedTemplateName) ||
    normalizedName.includes('rnd') ||
    compactName.includes('연구개발')
  ) {
    return 'rnd_plan';
  }

  return 'business_plan';
};

export const sortDraftTemplateOptions = (
  templates: DraftTemplateOption[]
) => {
  const hasDisplayOrder = templates.some(
    ({ displayOrder }) => typeof displayOrder === 'number'
  );

  if (!hasDisplayOrder) {
    return templates;
  }

  return [...templates].sort((left, right) => {
    const leftOrder = left.displayOrder ?? Number.MAX_SAFE_INTEGER;
    const rightOrder = right.displayOrder ?? Number.MAX_SAFE_INTEGER;

    if (leftOrder !== rightOrder) {
      return leftOrder - rightOrder;
    }

    return left.name.localeCompare(right.name, 'ko');
  });
};

export const toDraftTemplateOption = (
  template: ProductFilePathMapContents
): DraftTemplateOption => {
  const name = getDraftTemplateName(template.filePath);

  return {
    id: template.productFileId,
    name,
    promptProfile: resolveDraftPromptProfile(name),
    displayOrder: template.displayOrder,
    isFreeDraftTemplate: template.isFreeDraftTemplate
  };
};
